          is_uneditable = is_uneditable,
          goal_reward = goal_reward,
          create_source = create_source,
          unknownFields = unknownFields
        )
      }

      override fun redact(`value`: LiveStreamGoal): LiveStreamGoal = value.copy(
        sub_goals = value.sub_goals.redactElements(LiveStreamSubGoal.ADAPTER),
        contributors = value.contributors.redactElements(LiveStreamGoalContributor.ADAPTER),
        stats = value.stats?.let(GoalStats.ADAPTER::redact),
        audit_info = value.audit_info?.let(AuditInfo.ADAPTER::redact),
        goal_reward = value.goal_reward?.let(GoalReward.ADAPTER::redact),
        unknownFields = ByteString.EMPTY
      )
    }

    private const val serialVersionUID: Long = 0L
  }
}
